import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { Plus, Save, Trash2, UserPlus } from 'lucide-react';
import { useBusinessCrm } from '../BusinessCrmContext';
import { crmApi, messageFromError } from '../api';
import { crmPath, formatMoney, today } from '../constants';
import { offlineDb } from '../offline/db';
import { queueOperation } from '../offline/queue';
import { Button, Card, Combobox, ErrorState, Field, Input, Loading, Modal, PageHeader, Select, Textarea } from '../components/ui';

// One page of suggestions per keystroke-settled search. The previous form loaded 500 clients, 500
// vendors and 500 products before it would render at all, then put every one of them into a <select>.
const SUGGEST_PAGE = 25;
const blankQuickClient = () => ({ name: '', whatsapp: '', email: '' });

const MONEY = /^-?\d+(?:\.\d{1,2})?$/;
const CURRENCY = /^[A-Z]{3}$/;

/**
 * Reads the balance rows out of the authorised contact-detail response.
 *
 * The endpoint answers `{ ...contact, sales, tasks, activities, totals }` - contact fields at the
 * TOP LEVEL - and each total is `{ currency_code, total_amount, paid_amount, pending_amount,
 * sale_count }` with money.normalize already applied.
 *
 * Returns an ARRAY when the response is usable (possibly empty, which legitimately means this
 * contact has no sales at all), or NULL when it is missing or malformed. Null must be shown as a
 * failure: a confident "no outstanding" is a statement about money and may only be made from data
 * we actually understood.
 */
function readTotals(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return null;
  if (!Array.isArray(body.totals)) return null;                 // absent or wrong type - unusable
  const rows = [];
  for (const row of body.totals) {
    if (!row || typeof row !== 'object') return null;
    const code = String(row.currency_code || '');
    if (!CURRENCY.test(code)) return null;
    const pending = String(row.pending_amount);
    if (!MONEY.test(pending)) return null;                      // e.g. null, "", "abc", 1.2345
    rows.push({ currency_code: code, pending_amount: pending });
  }
  return rows;
}

/** Only the fields the read-only summary displays; history and tasks are deliberately dropped. */
function contactFields(body) {
  if (!body || typeof body !== 'object') return null;
  const { name, whatsapp, email, company } = body;
  return (name || whatsapp || email || company) ? { name, whatsapp, email, company } : null;
}

const blankItem = () => ({
  id: '', productId: '', name: '', accountType: 'private', durationLabel: '1 Month',
  purchaseDate: today(), expiryDate: '', credentialEmail: '', credentialPassword: '',
  keepCredentialEmail: false, keepCredentialPassword: false, salePrice: '0.00', purchaseCost: '0.00',
});
const initialForm = (currency) => ({
  clientId: '', vendorId: '', saleDate: today(), orderType: 'new', currencyCode: currency,
  notes: '', invoiceInstructions: '', openingClientPayment: '0.00', openingVendorPayment: '0.00',
  paymentMethod: 'Cash', version: 1, items: [blankItem()],
});

export default function SaleForm() {
  const { id } = useParams();
  const editing = Boolean(id);
  const crm = useBusinessCrm();
  const navigate = useNavigate();
  const costVisible = crm.has('profit.view');
  const vendorVisible = crm.has('vendors.view');
  const clientPaymentAllowed = crm.has('payments.client.record');
  const vendorPaymentAllowed = crm.has('payments.vendor.record');
  const credentialsManage = crm.has('credentials.manage');
  const credentialsView = crm.has('credentials.view');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);
  const [clients, setClients] = useState([]);
  const [vendors, setVendors] = useState([]);
  const [products, setProducts] = useState([]);
  const [currencyLocked, setCurrencyLocked] = useState(false);
  const [form, setForm] = useState(() => initialForm(crm.currency));
  // The combobox shows a label for the current selection. Kept OUTSIDE `form` on purpose: the submit
  // payload spreads `form` wholesale, and the sale schema would reject unknown keys.
  const [clientLabel, setClientLabel] = useState('');
  const [vendorLabel, setVendorLabel] = useState('');
  // SELECTED-CLIENT SUMMARY. Read-only. Name, phone, email and company come from the suggestion
  // that was already fetched, so selecting costs no extra request for them. Only the outstanding
  // balance needs the authorised detail call, and because that endpoint returns totals GROUPED BY
  // currency_code, switching currency re-reads the same response instead of fetching again.
  //
  // `state` keeps four outcomes apart that would otherwise all look like "0": not asked yet,
  // loading, the lookup FAILED (balance unknown), and a confirmed zero.
  const [clientSummary, setClientSummary] = useState(null);
  const summaryTicket = useRef(0);
  const accountId = String(crm.bootstrap?.user?.id || '');

  const loadClientSummary = useCallback((id, contact) => {
    if (!id) return;
    const mine = summaryTicket.current + 1; summaryTicket.current = mine;
    setClientSummary({ id, account: accountId, contact: contact || null, state: 'loading', totals: null });
    crmApi.get(`/contacts/clients/${id}`)
      .then((response) => {
        // Guarded by ticket AND by id/account, so a late answer for client A cannot land on B.
        if (mine !== summaryTicket.current) return;
        const body = response && response.data;
        const totals = readTotals(body);
        setClientSummary((current) => {
          if (!(current && current.id === id && current.account === accountId)) return current;
          // An unusable response is a FAILURE, not an empty balance. Converting a missing or
          // malformed `totals` into [] would have the panel state "None in PKR" - a confident
          // claim about someone's money derived from a response we could not read.
          if (totals === null) return { ...current, state: 'failed', totals: null };
          // The existing-sale path seeds a NAME-ONLY stub, so `current.contact || ...` kept that
          // stub and threw away the phone/email/company this very response just returned. Prefer
          // the fresh authorised values; a field the operator has deliberately CLEARED comes back
          // as null/'' and must be shown as cleared, not restored from the stale seed.
          const fresh = contactFields(body);
          return { ...current, state: 'ready', totals, contact: fresh || current.contact };
        });
      })
      .catch(() => {
        if (mine !== summaryTicket.current) return;
        setClientSummary((current) => (current && current.id === id ? { ...current, state: 'failed' } : current));
      });
  }, [accountId]);

  const clearClientSummary = useCallback(() => { summaryTicket.current += 1; setClientSummary(null); }, []);
  useEffect(() => { clearClientSummary(); }, [accountId, clearClientSummary]);
  // Unmount invalidates any outstanding detail request. No interval or polling is introduced.
  useEffect(() => () => { summaryTicket.current += 1; }, []);

  const [quickClient, setQuickClient] = useState(null);
  const [quickSaving, setQuickSaving] = useState(false);
  const [quickError, setQuickError] = useState('');

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true); setError('');
      try {
        const saleResponse = editing ? await crmApi.get(`/sales/${id}${credentialsView ? '?credentials=1' : ''}`) : null;
        if (!active) return;
        if (saleResponse) {
          const sale = saleResponse.data;
          setCurrencyLocked(Number(sale.client_paid || 0) > 0 || Number(sale.vendor_paid || 0) > 0);
          setClientLabel(sale.client_name || '');
          // Read-only: shows the saved client's CURRENT balance. It reprices nothing, resets no
          // item and writes no contact data.
          if (sale.client_id) loadClientSummary(sale.client_id, { name: sale.client_name });
          setVendorLabel(sale.vendor_name || '');
          setForm({
            clientId: sale.client_id, vendorId: sale.vendor_id || '', saleDate: sale.sale_date,
            orderType: sale.order_type, currencyCode: sale.currency_code, notes: sale.notes || '',
            invoiceInstructions: sale.invoice_instructions || '', openingClientPayment: '0.00', openingVendorPayment: '0.00',
            paymentMethod: 'Cash', version: sale.version,
            items: (sale.items || []).map((item) => ({
              id: item.id, productId: item.product_id || '', name: item.name, accountType: item.account_type,
              durationLabel: item.duration_label || '', purchaseDate: item.purchase_date || '', expiryDate: item.expiry_date || '',
              credentialEmail: item.credential_email || '', credentialPassword: item.credential_password || '',
              keepCredentialEmail: Boolean(item.has_credential_email), keepCredentialPassword: Boolean(item.has_credential_password),
              salePrice: item.sale_price, purchaseCost: item.purchase_cost ?? '0.00',
            })),
          });
        } else setForm(initialForm(crm.currency));
        if (!navigator.onLine) await loadOfflineLists(saleResponse?.data?.currency_code || crm.currency, active);
      } catch (requestError) {
        if (!navigator.onLine && !editing) {
          await loadOfflineLists(crm.currency, active);
          if (active) setForm(initialForm(crm.currency));
        } else if (active) setError(messageFromError(requestError));
      } finally { if (active) setLoading(false); }
    })();

    async function loadOfflineLists(currency, stillActive) {
      const [clientCache, vendorCache, productCache] = await Promise.all([
        offlineDb.getCache('clients'),
        vendorVisible ? offlineDb.getCache('vendors') : Promise.resolve(null),
        offlineDb.getCache(`products:${currency}`),
      ]);
      if (!stillActive || !active) return;
      setClients(clientCache?.value || []); setVendors(vendorCache?.value || []); setProducts(productCache?.value || []);
      if (!clientCache?.value?.length || !productCache?.value?.length) setError('Connect once before creating an offline sale so clients and products can be cached.');
    }
    return () => { active = false; };
  }, [id, editing, crm.currency, vendorVisible, credentialsView]);

  // Offline cache warming is deliberately OUTSIDE the load path above, so the form renders as soon as
  // the sale itself has arrived. The bulk lists exist only to make an offline sale possible; making
  // the operator wait for them before the first field is usable was the reason this page felt slow.
  const warmCurrency = form.currencyCode;
  useEffect(() => {
    if (!navigator.onLine) return undefined;
    let active = true;
    const warm = async (key, url, apply) => {
      try {
        const response = await crmApi.get(url);
        if (!active) return;
        const rows = response.data.rows || [];
        apply(rows);
        await offlineDb.putCache(key, rows);
      } catch { /* Cache warming is best effort: a failure here must not surface as a form error. */ }
    };
    // MEASURED, in the rendered form: this effect used to depend on the currency as well, so
    // switching PKR -> INR re-issued THREE pageSize=500 requests - clients and vendors included -
    // although neither list is currency-scoped. Only the product catalogue is. Splitting the
    // dependency is the minimal separation; nothing else about the warm-up changes, and it is
    // still real background work (see the measurement test).
    warm('clients', '/contacts/clients?pageSize=500', setClients);
    if (vendorVisible) warm('vendors', '/contacts/vendors?pageSize=500', setVendors);
    return () => { active = false; };
  }, [vendorVisible]);

  useEffect(() => {
    if (!navigator.onLine) return undefined;
    let active = true;
    (async () => {
      try {
        const response = await crmApi.get(`/products?pageSize=500&currency=${warmCurrency}`);
        if (!active) return;
        const rows = response.data.rows || [];
        setProducts(rows);
        await offlineDb.putCache(`products:${warmCurrency}`, rows);
      } catch { /* best effort, as above */ }
    })();
    return () => { active = false; };
  }, [warmCurrency]);

  // Suggestion sources. Online they hit the module's own list endpoints with the same `q` filter the
  // list pages use; offline they fall back to the warmed cache so an offline sale is still possible.
  /**
   * `eligible` is applied to BOTH branches on purpose. `matches` is only the offline text filter,
   * so a predicate passed there would silently not apply to the online path - which is exactly the
   * path that matters for a live sale. Clients and vendors pass nothing and behave as before.
   */
  const suggest = useCallback(async (url, rows, matches, toOption, eligible) => {
    const allow = eligible || (() => true);
    if (navigator.onLine) {
      const response = await crmApi.get(url);
      return (response.data.rows || []).filter(allow).map(toOption);
    }
    return rows.filter(matches).filter(allow).slice(0, SUGGEST_PAGE).map(toOption);
  }, []);
  const searchClients = useCallback(async (text) => suggest(
    `/contacts/clients?pageSize=${SUGGEST_PAGE}&q=${encodeURIComponent(text)}`,
    clients,
    (row) => [row.name, row.whatsapp, row.email, row.company].some((field) => String(field || '').toLowerCase().includes(text.toLowerCase())),
    (row) => ({ id: row.id, label: row.name, hint: [row.company, row.whatsapp, row.email].filter(Boolean).join(' • ') || undefined, raw: row }),
  ), [suggest, clients]);
  const searchVendors = useCallback(async (text) => suggest(
    `/contacts/vendors?pageSize=${SUGGEST_PAGE}&q=${encodeURIComponent(text)}`,
    vendors,
    (row) => [row.name, row.whatsapp, row.email, row.company].some((field) => String(field || '').toLowerCase().includes(text.toLowerCase())),
    (row) => ({ id: row.id, label: row.name, hint: [row.company, row.whatsapp].filter(Boolean).join(' • ') || undefined, raw: row }),
  ), [suggest, vendors]);
  /**
   * An imported product whose commercial details are not confirmed yet is not offered here.
   *
   * This is a CONVENIENCE, not the safeguard: salesService refuses it server-side, inside the sale
   * transaction, for the direct route and the offline replay alike. Filtering here only avoids
   * showing the operator something that would be rejected - and, importantly, avoids offering a
   * row whose price the API has deliberately blanked, which would otherwise auto-fill as empty.
   *
   * `row.source` is absent for a manual product, so manual products are never filtered.
   */
  const sellable = useCallback((row) => !row.source || row.source.sellable === true, []);
  const searchProducts = useCallback(async (text) => suggest(
    `/products?pageSize=${SUGGEST_PAGE}&currency=${form.currencyCode}&q=${encodeURIComponent(text)}`,
    products,
    (row) => [row.name, row.category].some((field) => String(field || '').toLowerCase().includes(text.toLowerCase())),
    (row) => ({ id: row.id, label: row.name, hint: [row.category, row.duration_label, formatMoney(row.default_sale_price, row.currency_code)].filter(Boolean).join(' • '), raw: row }),
    sellable,
  ), [suggest, products, form.currencyCode, sellable]);

  // Synchronous, like the sale guard: `quickSaving` only disables the button on the next paint,
  // and two clicks inside that frame created TWO contacts (observed in test).
  const quickInFlight = useRef(false);
  // Cancelling the modal, or any later deliberate selection, supersedes an in-flight create so its
  // late answer cannot select a client the operator has already moved away from (also observed).
  const quickGeneration = useRef(0);
  // Key bound to the exact submitted payload: an edit mints a new one, an unchanged retry reuses it.
  const quickAttempt = useRef({ key: null, payload: null });
  // An attempt whose outcome is UNKNOWN (no response / 5xx). The contact may already exist, so the
  // key and the exact body that was sent are frozen: editing the name or phone must not mint a new
  // identity for money-adjacent data that may already be recorded.
  const quickUnresolved = useRef(null);
  const [quickUnresolvedState, setQuickUnresolvedState] = useState(false);
  // Set when a reconciliation confirmed the ORIGINAL contact while the operator had typed
  // something different. Display-only; it never writes.
  const [quickReconciled, setQuickReconciled] = useState(null);

  const createQuickClient = async () => {
    if (quickInFlight.current) return;
    quickInFlight.current = true;
    const mine = quickGeneration.current + 1; quickGeneration.current = mine;
    setQuickSaving(true); setQuickError('');
    let dispatchedOp = null;
    try {
      // ONE identity for one intended contact. The synchronous guard stops simultaneous clicks; it
      // does nothing about a committed request whose RESPONSE was lost, where a second attempt
      // would otherwise create a duplicate contact. contactService replays on this key and the
      // column is UNIQUE, so the same key is the same contact.
      const base = { name: quickClient.name.trim(), whatsapp: quickClient.whatsapp.trim() || '', email: quickClient.email.trim() || '', company: '', address: '', taxId: '', notes: '', status: 'active' };
      const serialised = JSON.stringify(base);
      if (!quickUnresolved.current && quickAttempt.current.payload !== serialised) {
        let fresh;
        try { fresh = window.crypto && window.crypto.randomUUID ? window.crypto.randomUUID() : null; } catch (_) { fresh = null; }
        quickAttempt.current = { key: fresh || `contact-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`, payload: serialised };
      }
      // While unresolved, send the ORIGINAL body under the ORIGINAL key. Any edits made since stay
      // in the form - they are a PROPOSAL, and the notice says so rather than implying they were
      // saved. Reconciling first is what stops one uncertain contact becoming two.
      const sendBase = quickUnresolved.current ? JSON.parse(quickUnresolved.current.payload) : base;
      const payload = { ...sendBase, idempotencyKey: quickUnresolved.current ? quickUnresolved.current.key : quickAttempt.current.key };
      if (!payload.name) throw new Error('Client name is required.');
      dispatchedOp = { key: payload.idempotencyKey, payload: JSON.stringify(sendBase) };
      const response = await crmApi.post('/contacts/clients', payload);
      const created = response.data?.id ? response.data : response.data?.client;
      // The operation is resolved either way - that is bookkeeping, not ownership.
      const wasReconciling = Boolean(quickUnresolved.current);
      quickUnresolved.current = null; setQuickUnresolvedState(false);
      if (mine !== quickGeneration.current) return;   // superseded: do not select, do not reopen

      // WHAT WAS ACTUALLY SAVED. On a reconciliation the server replays the ORIGINAL row, so any
      // values typed after the uncertain attempt were never sent. Saying nothing would let the
      // operator believe their correction was stored. Nothing is auto-updated and no second
      // contact is created: the difference is shown, and a correction goes through the existing
      // contact-edit screen.
      if (wasReconciling) {
        const typed = { name: quickClient.name.trim(), whatsapp: quickClient.whatsapp.trim() || '', email: quickClient.email.trim() || '' };
        const differing = Object.keys(typed).filter((field) => String(typed[field] || '') !== String(created[field] || ''));
        if (differing.length) {
          setQuickReconciled({ id: created.id, name: created.name, fields: differing.map((field) => ({ field, saved: created[field] || '-', typed: typed[field] || '-' })) });
        }
      }
      // Selecting the new client only touches these two pieces of state, so everything already typed
      // into the sale — items, prices, credentials, notes — is still there when the modal closes.
      update('clientId', created.id);
      setClientLabel(created.name);
      // Same single mechanism as the dropdown, so a client created here shows the same authorised
      // summary. The CONFIRMED server record is passed in, never the typed form values.
      loadClientSummary(created.id, contactFields(created));
      setClients((current) => [created, ...current]);
      setQuickClient(null);
    } catch (requestError) {
      const status = requestError?.response?.status;
      // Only a request that actually went out and gave no usable answer is uncertain. A local
      // "name is required" or an explicit 4xx is a definite refusal: the operator corrects it and
      // submits normally under a fresh key.
      const uncertain = Boolean(dispatchedOp) && (status === undefined || status >= 500);

      // BOOKKEEPING FIRST, regardless of who owns the dialog now. Closing the modal or selecting
      // another client does NOT cancel a request already sent, so forgetting it here is how a
      // possibly-committed contact becomes invisible and then gets created a second time. The
      // generation check below only governs what may be written to the SCREEN.
      if (uncertain) { quickUnresolved.current = dispatchedOp; setQuickUnresolvedState(true); }

      if (mine !== quickGeneration.current) return;   // superseded: do not touch the selection
      setQuickError(uncertain
        ? 'This contact may already have been created - the result is unknown. Press "Save and select" again to check with the same operation key. Any edits you make now are NOT saved yet and will not be sent until that is resolved.'
        : messageFromError(requestError));
    }
    finally { quickInFlight.current = false; setQuickSaving(false); }
  };

  const totals = useMemo(() => form.items.reduce((sum, item) => ({ sale: sum.sale + Number(item.salePrice || 0), cost: sum.cost + Number(item.purchaseCost || 0) }), { sale: 0, cost: 0 }), [form.items]);
  const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const updateItem = (index, key, value) => setForm((current) => ({ ...current, items: current.items.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item) }));
  const changeCurrency = (currencyCode) => {
    if (currencyLocked) return;
    // Items are cleared because catalogue prices are per-currency. The product cache for the new
    // currency is warmed by the effect above, which keys on form.currencyCode.
    setForm((current) => ({ ...current, currencyCode, items: current.items.map(() => blankItem()) }));
  };
  const clearProduct = (index) => setForm((current) => ({
    ...current,
    items: current.items.map((item, itemIndex) => itemIndex === index
      ? { ...item, productId: '', ...(costVisible ? {} : { name: '' }) }
      : item),
  }));
  // Auto-fill is unchanged in behaviour; it now receives the product record straight from the chosen
  // suggestion instead of looking it up in a 500-row array that had to be loaded up front.
  const pickProduct = (index, product) => {
    if (!product) { clearProduct(index); return; }
    setForm((current) => ({
      ...current,
      items: current.items.map((item, itemIndex) => itemIndex === index ? {
        ...item, productId: product.id, name: product.name, accountType: product.account_type,
        durationLabel: product.duration_label || '', salePrice: product.default_sale_price,
        purchaseCost: product.default_purchase_cost ?? item.purchaseCost ?? '0.00',
      } : item),
    }));
  };

  // Sale creation already had a `saving` flag and a disabled button. Two protections were still
  // missing, and both are reachable: `validation.js` permits `idempotencyKey` on `saleCreate`, and
  // `salesService` checks it (SELECT ... WHERE idempotency_key). Its replay rule is LOOSER than the
  // payment one - it compares only the creator and returns the existing sale, ignoring the new
  // payload entirely - so a key reused after editing the items would silently return the old sale.
  // The key is therefore bound to the exact payload: identical payload (a retry) reuses it, any
  // edit mints a new one. `editing` is excluded; PUT is version-checked, not idempotency-keyed.
  const attempt = useRef({ key: null, payload: null });
  // An attempt whose outcome is unknown (no response / 5xx). The sale may already be committed with
  // its invoice number and opening payments, so the next submit must NOT become a second sale under
  // a fresh identity. Both the key AND the exact payload sent are held, and the retry re-sends
  // those, not whatever the form now contains.
  const [unresolvedSale, setUnresolvedSale] = useState(null);
  const unresolvedRef = useRef(null);
  const pendingPayload = useRef(null);

  const keyForPayload = (serialised) => {
    // While unresolved, the key is frozen: minting a new one after a possibly-committed create is
    // exactly how a duplicate invoice is produced.
    if (unresolvedRef.current) return unresolvedRef.current.key;
    if (attempt.current.payload !== serialised) {
      let key;
      try { key = window.crypto && window.crypto.randomUUID ? window.crypto.randomUUID() : null; } catch (_) { key = null; }
      attempt.current = { key: key || `sale-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`, payload: serialised };
    }
    return attempt.current.key;
  };
  // Synchronous: `setSaving(true)` only disables the button on the next paint, which leaves a
  // window a fast double-submit can pass through.
  const inFlight = useRef(false);

  const submit = async (event) => {
    event.preventDefault();
    if (inFlight.current) return;
    inFlight.current = true;
    setSaving(true); setError('');
    // Only a request that was actually DISPATCHED can have an uncertain result. Local validation
    // throws below (a missing catalogue product, the offline refusals) happen before anything is
    // sent, and treating those as an unknown sale outcome froze the form over a sale that never
    // left the browser. `confirmed` separates a completed save from a later navigation/render
    // error, which must not reopen the uncertain path either.
    let dispatched = null;      // { key, payload } exactly as sent - never null when used
    let confirmed = false;
    try {
      const items = form.items.map((item) => {
        const output = {
          ...item, id: item.id || null, productId: item.productId || null,
          purchaseDate: item.purchaseDate || null, expiryDate: item.expiryDate || null,
        };
        if (!costVisible) delete output.purchaseCost;
        if (!credentialsManage) {
          delete output.credentialEmail; delete output.credentialPassword;
          delete output.keepCredentialEmail; delete output.keepCredentialPassword;
        }
        return output;
      });
      if (!costVisible && items.some((item) => !item.productId)) throw new Error('Select a catalogue product for every item. Custom costing requires Manager access.');
      const payload = {
        ...form, items,
        vendorId: vendorVisible ? (form.vendorId || null) : null,
        openingClientPayment: clientPaymentAllowed ? form.openingClientPayment : '0.00',
        openingVendorPayment: vendorPaymentAllowed ? form.openingVendorPayment : '0.00',
      };
      if (!navigator.onLine) {
        if (editing) throw new Error('Existing financial records can only be edited online.');
        // AN UNRESOLVED ONLINE CREATE MUST NOT BECOME A NEW OFFLINE SALE. The offline branch runs
        // before reconciliation, and queueOperation() mints its own `crypto.randomUUID()` - a
        // fresh identity. Queuing here would turn one possibly-committed sale into a second one
        // with its own invoice number on sync. Reconciliation needs the server, so the honest
        // answer is to wait for the connection; the frozen key and payload are kept meanwhile.
        // Legitimate NEW offline sales are unaffected: this only triggers while unresolved.
        if (unresolvedRef.current) {
          throw new Error('The earlier attempt for this sale has not been confirmed yet, so it cannot be queued offline - that would create a second sale. Reconnect and press Save sale again to check the original with the same operation key.');
        }
        if (!crm.has('offline.sync')) throw new Error('Your role cannot queue offline financial entries.');
        if (payload.items.some((item) => item.credentialEmail || item.credentialPassword)) throw new Error('Credentials cannot be stored in the offline queue. Remove them or reconnect.');
        const clean = { ...payload, items: payload.items.map(({ credentialEmail, credentialPassword, keepCredentialEmail, keepCredentialPassword, ...rest }) => rest) };
        await queueOperation('sale.create', clean, crm.bootstrap?.user?.id); crm.setQueued(crm.queued + 1); navigate(crmPath('sales')); return;
      }
      // A retry of an unresolved create re-sends the ORIGINAL payload under the ORIGINAL key, so
      // the server can recognise it as the same operation and replay rather than create again.
      pendingPayload.current = payload;
      const resend = !editing && unresolvedRef.current;
      const sent = resend ? unresolvedRef.current.payload : payload;
      const body = editing ? sent : { ...sent, idempotencyKey: keyForPayload(JSON.stringify(sent)) };
      // Captured BEFORE dispatch, so an uncertain outcome always has a real key and payload to
      // reconcile with rather than a null one.
      if (!editing) dispatched = { key: body.idempotencyKey, payload: sent };
      const response = editing ? await crmApi.put(`/sales/${id}`, body) : await crmApi.post('/sales', body);
      confirmed = true;
      unresolvedRef.current = null; setUnresolvedSale(null);
      navigate(crmPath(`sales/${response.data.id}`));
    } catch (requestError) {
      const status = requestError?.response?.status;
      if (!editing && dispatched && !confirmed && (status === undefined || status >= 500)) {
        // A request really went out and gave no usable answer. The sale may exist.
        const frozen = unresolvedRef.current || dispatched;
        unresolvedRef.current = frozen; setUnresolvedSale(frozen);
        setError('The result of this sale is unknown - it may already have been created with its invoice number. Press Save sale again to check with the same operation key. Do not change the form: an edit would create a second sale.');
      } else {
        setError(messageFromError(requestError));
      }
    }
    finally { inFlight.current = false; setSaving(false); }
  };

  if (loading) return <Loading />;
  if (error && editing && !form.clientId) return <ErrorState message={error} />;

  return <form onSubmit={submit}>
    <PageHeader title={editing ? 'Edit sale' : 'Create sale'} description="Invoice, access delivery and approved ledgers are recorded in one controlled transaction." actions={<><Button type="button" variant="secondary" onClick={() => navigate(-1)}>Cancel</Button><Button type="submit" icon={Save} disabled={saving}>{saving ? 'Saving…' : 'Save sale'}</Button></>} />
    {error && <div className="bcrm-banner warning">{error}</div>}
    <Card title="Invoice details" subtitle="Currency becomes locked after the first posted payment">
      <div className="bcrm-form-grid bcrm-form-grid-3">
        <Field label="Client" hint="Search by name, phone, email or company">
          <Combobox
            name="clientId" required value={form.clientId} valueLabel={clientLabel} search={searchClients}
            placeholder="Search clients…" emptyHint="No client matches that search"
            onSelect={(option) => { quickGeneration.current += 1; update('clientId', option.id); setClientLabel(option.label); loadClientSummary(option.id, option.raw || { name: option.label }); }}
            onClear={() => { update('clientId', ''); setClientLabel(''); clearClientSummary(); }}
            footer={crm.has('clients.create') && <Button type="button" variant="ghost" icon={UserPlus} onClick={() => {
              setQuickError(quickUnresolved.current ? 'An earlier contact attempt is still unconfirmed. Press "Save and select" to check it with the same operation key before creating anything new.' : '');
              setQuickClient(blankQuickClient());
            }}>Create new client</Button>}
          />
          {quickReconciled && <div className="bcrm-banner warning" role="status">
            <strong>Reconciled to the contact that was already created.</strong> Your later edits were not sent, so these values are the saved ones:
            <ul className="bcrm-reconciled">
              {quickReconciled.fields.map((row) => <li key={row.field}><span>{row.field}</span> saved as <strong>{row.saved}</strong>, you typed <em>{row.typed}</em></li>)}
            </ul>
            <Link to={crmPath(`clients/${quickReconciled.id}`)}>Open the contact to correct it</Link>
            {' '}&middot;{' '}
            <button type="button" className="bcrm-clientsum-retry" onClick={() => setQuickReconciled(null)}>Keep the saved values</button>
          </div>}
          {clientSummary && clientSummary.id === form.clientId && <div className="bcrm-clientsum" aria-live="polite">
            <div className="bcrm-clientsum-head">
              <strong>{clientSummary.contact?.name || clientLabel}</strong>
              <Link className="bcrm-clientsum-link" to={crmPath(`clients/${clientSummary.id}`)}>Open profile</Link>
            </div>
            <dl className="bcrm-clientsum-facts">
              {clientSummary.contact?.whatsapp && <><dt>Phone</dt><dd>{clientSummary.contact.whatsapp}</dd></>}
              {clientSummary.contact?.email && <><dt>Email</dt><dd>{clientSummary.contact.email}</dd></>}
              {clientSummary.contact?.company && <><dt>Company</dt><dd>{clientSummary.contact.company}</dd></>}
              <dt>Outstanding ({form.currencyCode})</dt>
              <dd>{(() => {
                // Four distinct outcomes - a failure must never read as a zero balance.
                if (clientSummary.state === 'loading') return <span className="bcrm-clientsum-muted">Checking…</span>;
                if (clientSummary.state === 'failed') return <span className="bcrm-clientsum-warn">Could not load — balance unknown{' '}
                  <button type="button" className="bcrm-clientsum-retry" onClick={() => loadClientSummary(clientSummary.id, clientSummary.contact)}>Retry</button>
                </span>;
                const row = (clientSummary.totals || []).find((total) => total.currency_code === form.currencyCode);
                if (!row) return <span className="bcrm-clientsum-muted">None in {form.currencyCode}</span>;
                return <strong>{formatMoney(row.pending_amount, form.currencyCode)}</strong>;
              })()}</dd>
            </dl>
          </div>}
        </Field>
        {vendorVisible && <Field label="Vendor" hint="Optional">
          <Combobox
            value={form.vendorId} valueLabel={vendorLabel} search={searchVendors}
            placeholder="Search vendors…" emptyHint="No vendor matches that search"
            onSelect={(option) => { update('vendorId', option.id); setVendorLabel(option.label); }}
            onClear={() => { update('vendorId', ''); setVendorLabel(''); }}
          />
        </Field>}
        <Field label="Sale date"><Input type="date" required value={form.saleDate} onChange={(event) => update('saleDate', event.target.value)} /></Field>
        <Field label="Order type"><Select value={form.orderType} onChange={(event) => update('orderType', event.target.value)}><option value="new">New</option><option value="renewal">Renewal</option></Select></Field>
        <Field label="Currency" hint={currencyLocked ? 'Locked because a payment is already posted.' : 'PKR, INR and NGN remain separate ledgers.'}><Select value={form.currencyCode} onChange={(event) => changeCurrency(event.target.value)} disabled={currencyLocked}>{['PKR', 'INR', 'NGN'].map((code) => <option key={code}>{code}</option>)}</Select></Field>
        {(clientPaymentAllowed || vendorPaymentAllowed) && <Field label="Payment method"><Select value={form.paymentMethod} onChange={(event) => update('paymentMethod', event.target.value)}><option>Cash</option><option>Bank</option><option>JazzCash</option><option>Easypaisa</option><option>UPI</option><option>Other</option></Select></Field>}
      </div>
    </Card>
    <Card title="Products & access" subtitle="Maximum 20 items. Sensitive access data is encrypted only after it reaches the server." className="bcrm-section">
      {form.items.map((item, index) => <div className="bcrm-sale-item" key={item.id || index}>
        <div className="bcrm-item-title"><strong>Item {index + 1}</strong>{form.items.length > 1 && <button type="button" onClick={() => setForm((current) => ({ ...current, items: current.items.filter((_, itemIndex) => itemIndex !== index) }))} aria-label={`Remove item ${index + 1}`}><Trash2 size={15} /></button>}</div>
        <div className="bcrm-form-grid bcrm-form-grid-3">
          <Field label="Catalogue product" hint={costVisible ? 'Leave empty for a custom item' : 'Required for your role'}>
            <Combobox
              required={!costVisible} value={item.productId} valueLabel={item.productId ? item.name : ''} search={searchProducts}
              placeholder={costVisible ? 'Search catalogue, or leave empty' : 'Search catalogue…'}
              emptyHint={`No ${form.currencyCode} product matches that search`}
              onSelect={(option) => pickProduct(index, option.raw)}
              onClear={() => clearProduct(index)}
            />
          </Field>
          <Field label="Product / service"><Input required readOnly={!costVisible} value={item.name} onChange={(event) => updateItem(index, 'name', event.target.value)} /></Field>
          <Field label="Account type"><Select value={item.accountType} onChange={(event) => updateItem(index, 'accountType', event.target.value)}><option value="private">Private</option><option value="shared">Shared</option><option value="service">Service</option><option value="other">Other</option></Select></Field>
          <Field label="Duration"><Input value={item.durationLabel} onChange={(event) => updateItem(index, 'durationLabel', event.target.value)} /></Field>
          <Field label="Purchase date"><Input type="date" value={item.purchaseDate} onChange={(event) => updateItem(index, 'purchaseDate', event.target.value)} /></Field>
          <Field label="Expiry date"><Input type="date" value={item.expiryDate} onChange={(event) => updateItem(index, 'expiryDate', event.target.value)} /></Field>
          <Field label="Sale price"><Input required inputMode="decimal" value={item.salePrice} onChange={(event) => updateItem(index, 'salePrice', event.target.value)} /></Field>
          {costVisible && <Field label="Purchase cost"><Input required inputMode="decimal" value={item.purchaseCost} onChange={(event) => updateItem(index, 'purchaseCost', event.target.value)} /></Field>}
          {credentialsManage && <><Field label="Customer login"><Input autoComplete="off" value={item.credentialEmail} placeholder={item.keepCredentialEmail ? 'Stored — leave blank to keep' : ''} onChange={(event) => updateItem(index, 'credentialEmail', event.target.value)} /></Field><Field label="Customer password"><Input type="password" autoComplete="new-password" value={item.credentialPassword} placeholder={item.keepCredentialPassword ? 'Stored — leave blank to keep' : ''} onChange={(event) => updateItem(index, 'credentialPassword', event.target.value)} /></Field></>}
        </div>
      </div>)}
      {form.items.length < 20 && <div className="bcrm-form-actions"><Button type="button" variant="secondary" icon={Plus} onClick={() => setForm((current) => ({ ...current, items: [...current.items, blankItem()] }))}>Add item</Button></div>}
      <div className="bcrm-totalbar">
        <div><span>Invoice total</span><strong>{formatMoney(totals.sale, form.currencyCode)}</strong></div>
        {costVisible && <><div><span>Purchase cost</span><strong>{formatMoney(totals.cost, form.currencyCode)}</strong></div><div><span>Gross profit</span><strong>{formatMoney(totals.sale - totals.cost, form.currencyCode)}</strong></div></>}
      </div>
    </Card>
    {(clientPaymentAllowed || vendorPaymentAllowed) && <Card title="Opening payments" subtitle="Amounts cannot exceed the corresponding ledger total" className="bcrm-section"><div className="bcrm-form-grid">
      {clientPaymentAllowed && <Field label="Client received now"><Input inputMode="decimal" value={form.openingClientPayment} onChange={(event) => update('openingClientPayment', event.target.value)} /></Field>}
      {vendorPaymentAllowed && vendorVisible && <Field label="Vendor paid now"><Input inputMode="decimal" value={form.openingVendorPayment} onChange={(event) => update('openingVendorPayment', event.target.value)} /></Field>}
    </div></Card>}
    <Card title="Notes & invoice instructions" className="bcrm-section"><div className="bcrm-form-grid"><Field label="Internal notes"><Textarea value={form.notes} onChange={(event) => update('notes', event.target.value)} /></Field><Field label="Customer invoice instructions"><Textarea value={form.invoiceInstructions} onChange={(event) => update('invoiceInstructions', event.target.value)} /></Field></div></Card>
    {/*
      Quick client capture. Only Name is required; the full client record can be completed later from
      the Clients page. This creates a CRM contact and nothing else — no website assignment, no tool
      access and no portal login, which the existing website access flows continue to own.
    */}
    <Modal
      open={Boolean(quickClient)} title="Create new client" onClose={() => { quickGeneration.current += 1; setQuickClient(null); }}
      footer={<><Button type="button" variant="secondary" onClick={() => { quickGeneration.current += 1; setQuickClient(null); }}>Cancel</Button><Button type="button" icon={Save} onClick={createQuickClient} disabled={quickSaving || !quickClient?.name?.trim()}>{quickSaving ? 'Saving…' : 'Save and select'}</Button></>}
    >
      {quickClient && <>
        {quickError && <div className="bcrm-banner warning">{quickError}</div>}
        <p className="bcrm-modal-note">This adds a CRM contact only. It grants no tool access and creates no website assignment.</p>
        <div className="bcrm-form-grid">
          <Field label="Name"><Input autoFocus value={quickClient.name} onChange={(event) => setQuickClient({ ...quickClient, name: event.target.value })} /></Field>
          <Field label="WhatsApp" hint="Optional"><Input value={quickClient.whatsapp} onChange={(event) => setQuickClient({ ...quickClient, whatsapp: event.target.value })} /></Field>
          <Field label="Email" hint="Optional"><Input type="email" value={quickClient.email} onChange={(event) => setQuickClient({ ...quickClient, email: event.target.value })} /></Field>
        </div>
      </>}
    </Modal>
  </form>;
}
