import { useEffect, useState } from 'react';
import { RefreshCw } from 'lucide-react';
import { useDebouncedValue, useResource } from '../hooks';
import { formatDate } from '../constants';
import { Button, Card, ErrorState, Field, Input, Loading, PageHeader, Pager, SearchBox, Table } from '../components/ui';
export default function AuditPage(){const[action,setAction]=useState('');const[actor,setActor]=useState('');const dAction=useDebouncedValue(action);const dActor=useDebouncedValue(actor);const[page,setPage]=useState(1);useEffect(()=>{setPage(1)},[dAction,dActor]);const r=useResource(()=>`/admin/audit?page=${page}&pageSize=25&action=${encodeURIComponent(dAction)}&actor=${encodeURIComponent(dActor)}`,[dAction,dActor,page]);useEffect(()=>{const t=Number(r.data?.total??0),ps=Number(r.data?.pageSize??25);if(!r.loading&&t>0&&page>1&&(page-1)*ps>=t)setPage(Math.max(1,Math.ceil(t/ps)))},[r.data,r.loading,page]);if(r.initialLoading)return <Loading label="Loading audit trail…"/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;return <><PageHeader title="Immutable activity audit" description="Who changed what, when, from which request and device context." actions={<Button variant="secondary" icon={RefreshCw} onClick={r.reload}>Refresh</Button>}/><div className="bcrm-filterbar"><SearchBox value={action} onChange={setAction} busy={r.loading} label="Filter by audit action key" placeholder="Exact action key…"/><Field label="Actor user ID"><Input value={actor} onChange={e=>setActor(e.target.value)} placeholder="Optional exact ID"/></Field></div><Card className="flush" title={`${r.data?.total||0} audit events`} subtitle="Change snapshots are never sent to the browser"><Table rows={r.data?.rows||[]} columns={[{key:'created_at',label:'Time',render:x=>formatDate(x.created_at,true)},{key:'action_key',label:'Action',render:x=><span title={x.action_key}>{x.action_label||x.action_key}</span>},{key:'actor_user_id',label:'Actor',render:x=><span title={x.actor_user_id}>{x.actor_name||x.actor_user_id}</span>},{key:'actor_role',label:'Role'},{key:'entity_type',label:'Entity'},{key:'entity_id',label:'Record ID'},{key:'ip_address',label:'IP'},{key:'request_id',label:'Request ID'}]}/><Pager page={r.data?.page} pageSize={r.data?.pageSize} total={r.data?.total} shown={r.data?.rows?.length} busy={r.loading} onPage={setPage} noun="audit events"/></Card></>}
